function filter$permission(p){
  this.constructor(p);
}
filter$permission.prototype = new DirEvent();

filter$permission.prototype.afterInit = function(){
  var p = this._dir, e = p.element, g = p.options.parent;
  var f = e.find('.treeview').parent().parent();
  p.wait(true);
  p.valForm('group_id', g.valGrid(g.curr("r"), "group_id"));
  f.html('<div id="treeviewPanel" style="width: 715px; height: 380px;"></div>');

  var xmlhttp;
  if (window.XMLHttpRequest) xmlhttp = new XMLHttpRequest();
  else {
    try {xmlhttp = new ActiveXObject('Msxml2.XMLHTTP');}
      catch (ex) {xmlhttp = new ActiveXObject('Microsoft.XMLHTTP');}
  }

  xmlhttp.onreadystatechange = function() {
    if (xmlhttp.readyState == 4 && xmlhttp.status == 200) {
      p.tree = new TreeView('treeviewPanel', '100%', '100%', 0);
      p.tree.set_path('../Images/Tree/');
      p.tree.enableCheckBoxes(true);
      p.tree.loadXMLString(xmlhttp.responseText);
      p.wait(false);
    }
  }
  var param = 'Permission[@#]' + p.valForm('group_id') + '[@#]' + $.lan + '[@#]0[@#]allow[@#]' + new Date().getTime();
  xmlhttp.open('GET', '../AppHandler/FileHandler.ashx?param=' + $.encodeb64UTF8(param), true);
  xmlhttp.send(null);
}

filter$permission.prototype.beforeButtonDialogClick = function(id){
  var p = this._dir;
  if (id == 'filterOk') {
    var m = new Memvars(), dt = new DataTable(), a = p.tree.getAllCheckedBranches().split(','), k = a.length;
    dt.addColumn('C', 'data');
    while(k--) dt.addRow([a[k]])
    m.add([['permission', 'T', dt.sqlval()], ['group_id', 'N', p.valForm('group_id')]]);
    p.request('permission', 'GetRow', m, function(){p._close();});
    return false;
  }
  return true;
}








